style.css:
/* ===== ПЕРЕМЕННЫЕ DISCORD ===== */
:root {
    background-primary: #0e0e0e;
    background-secondary: #151515;
    background-secondary-alt: #1b1b1b;
    background-tertiary: #0b0b0b;
    background-accent: #222222;

    text-normal: #ffffff;
    text-muted: #b3b3b3;
    text-link: #ffffff;

    interactive-normal: #cccccc;
    interactive-hover: #ffffff;
    interactive-active: #ffffff;
}

/* ===== ОБЩИЙ ФОН ===== */
body {
    background-color: var(--background-primary) !important;
}

/* ===== ЧАТ ===== */
main {
    background-color: var(--background-primary) !important;
}

/* ===== САЙДБАРЫ ===== */
nav,
aside {
    background-color: var(--background-secondary) !important;
}

/* ===== СООБЩЕНИЯ ===== */
[class*="message"] {
    color: var(--text-normal) !important;
}

/* ===== НИКИ ===== */
[class*="username"] {
    color: #ffffff !important;
}

/* ===== ВТОРИЧНЫЙ ТЕКСТ ===== */
[class*="timestamp"],
[class*="system"] {
    color: var(--text-muted) !important;
}

/* ===== ПОЛЕ ВВОДА ===== */
textarea {
    background-color: var(--background-secondary-alt) !important;
    color: var(--text-normal) !important;
    border-radius: 8px;
}

/* ===== КНОПКИ ===== */
button {
    background-color: var(--background-accent) !important;
    color: #ffffff !important;
}

/* ===== УБРАТЬ ЦВЕТА РОЛЕЙ ===== */
span[style*="color"] {
    color: #ffffff !important;
}

/* ===== HOVER ===== */
button:hover,
[class*="clickable"]:hover {
    background-color: #2a2a2a !important;
}

/* ===== СКРОЛЛ ===== */
::-webkit-scrollbar {
    width: 8px;
}
::-webkit-scrollbar-thumb {
    background-color: #333333;
}
::-webkit-scrollbar-track {
    background-color: #111111;
}
